"""Automatically combine the four independently exported final figure runs."""
from pathlib import Path
import argparse,csv,hashlib,json,os,zipfile

DIRECTORIES=('01_proposed_convergence','02_wsr_vs_p_dl_max','03_wsr_vs_rho_si','04_wsr_vs_system_load')


def collect(toma,selection):
    frozen=selection/'frozen_initial_geometry.json'
    if not frozen.exists():return
    fingerprint=hashlib.sha256(frozen.read_bytes()).hexdigest();chosen={}
    for directory in DIRECTORIES:
        ready=[]
        for marker in (toma/directory/'results').glob('final_*/export_ready.json'):
            d=json.loads(marker.read_text(encoding='utf-8'))
            if d.get('frozen_sha256')==fingerprint:ready.append(marker)
        if not ready:
            print('Combined package pending:',directory,flush=True);return
        chosen[directory]=max(ready,key=lambda f:f.stat().st_mtime).parent
    dest=toma/'results';dest.mkdir(exist_ok=True)
    archive=dest/f'final_four_figures_{fingerprint[:12]}.zip';lock=archive.with_suffix('.lock')
    try:handle=lock.open('x')
    except FileExistsError:
        print('Another figure job is already assembling the combined package',flush=True);return
    try:
        handle.close();summary=dict(frozen_sha256=fingerprint,runs={})
        for directory,folder in chosen.items():
            data=dict(path=str(folder),completion=json.loads((folder/'completion.json').read_text(encoding='utf-8')),tables={})
            for table in (folder/'tables').glob('*.csv'):
                with table.open(encoding='utf-8-sig',newline='') as f:data['tables'][table.name]=list(csv.DictReader(f))
            summary['runs'][directory]=data
        summary_path=archive.with_suffix('.json');summary_path.write_text(json.dumps(summary,indent=2),encoding='utf-8')
        tmp=archive.with_suffix('.zip.tmp')
        with zipfile.ZipFile(tmp,'w',zipfile.ZIP_DEFLATED,compresslevel=4,allowZip64=True) as z:
            z.writestr('all_figures_summary.json',json.dumps(summary,indent=2))
            for directory,folder in chosen.items():
                for path in folder.rglob('*'):
                    if path.is_file() and not path.name.endswith('.tmp'):
                        z.write(path,directory+'/'+folder.name+'/'+path.relative_to(folder).as_posix())
        with zipfile.ZipFile(tmp) as z:
            if z.testzip() is not None:raise RuntimeError('Combined archive verification failed')
        os.replace(tmp,archive);print('ALL FOUR FIGURES PACKAGED:',archive,flush=True)
    finally:lock.unlink(missing_ok=True)


if __name__=='__main__':
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--toma-root',type=Path,default=Path(__file__).resolve().parent.parent)
    ap.add_argument('--selection-dir',type=Path,required=True)
    a=ap.parse_args();collect(a.toma_root.resolve(),a.selection_dir.resolve())

from __future__ import annotations


# ===== paper_figure_styles: shared implementation =====
"""One stable scheme -> marker/color mapping for every paper figure."""
STYLES={
 'proposed':dict(label='Proposed: ToMA + FP',marker='D',color='#df2228'),
 'b6':dict(label='MA + FP',marker='^',color='#279b3b'),
 'b2':dict(label='Fixed-ToMA + FP',marker='o',color='#e99a21'),
 'b3':dict(label='Fixed UPA + FP',marker='s',color='#2675c1'),
}
POWER_LINESTYLES=['-','--','-.',':']
POWER_COLORS=['#2675c1','#df2228','#8250a8','#9d6813']


# ===== paper_figures_unified: shared implementation =====
"""Shared experiment engine: original solvers, fixed starts, absolute stopping."""

import os
os.environ.setdefault('OPENBLAS_NUM_THREADS','1')
os.environ.setdefault('OMP_NUM_THREADS','1')
os.environ.setdefault('MKL_NUM_THREADS','1')
from pathlib import Path
from dataclasses import replace,asdict
from contextlib import ExitStack
from copy import deepcopy
from unittest.mock import patch
import csv,json,hashlib,time,shutil
import numpy as np
pass

FIGURES=['convergence','p_dl_max','rho_si','system_load','tradeoff']
FIELDS=['figure','parameter_value','scene_seed','scheme','sum_rate_dl','sum_rate_ul','sum_rate_comm','sum_rate_sensing','weighted_sum_rate','iterations','runtime_s','converged','calls']


def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def read_json(p):return json.loads(Path(p).read_text(encoding='utf-8'))
def json_write(p,d):
    p=Path(p);p.parent.mkdir(parents=True,exist_ok=True);tmp=p.with_suffix('.tmp')
    tmp.write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf-8');os.replace(tmp,p)
def csv_write(p,rows,fields):
    p=Path(p);p.parent.mkdir(parents=True,exist_ok=True);tmp=p.with_suffix('.tmp')
    with tmp.open('w',encoding='utf-8-sig',newline='') as f:
        writer=csv.DictWriter(f,fieldnames=fields);writer.writeheader();writer.writerows(rows)
    os.replace(tmp,p)
def serial(v):
    if isinstance(v,np.ndarray):return serial(v.tolist())
    if isinstance(v,complex):return [v.real,v.imag]
    if isinstance(v,np.generic):return serial(v.item())
    if isinstance(v,dict):return {str(k):serial(x) for k,x in v.items()}
    if isinstance(v,(tuple,list)):return [serial(x) for x in v]
    return v
def config_digest(cfg):return hashlib.sha256(json.dumps(serial(asdict(cfg)),sort_keys=True).encode()).hexdigest()
def abs_change(a,b):return abs(float(a)-float(b))

def solver_digest(p):
    return hashlib.sha256(json.dumps(p['protocol']['resource_solver'],sort_keys=True).encode()).hexdigest()

def stopping_tolerance(cfg,scheme):
    return cfg.tol_outer if scheme in ('proposed','b6') else cfg.tol_inner

def save_state(path,g,r,h):
    path=Path(path);tmp=path.with_suffix('.tmp')
    with tmp.open('wb') as f:
        np.savez_compressed(f,**{k:getattr(g,k) for k in ['endpoints','tx_positions','rx_positions']},
            **{k:getattr(r,k) for k in ['q_matrix','q_ul','b_ul','u_s']},wsr_history=np.asarray(h))
    os.replace(tmp,path)
def load_state(path):
    from system_model import GeometryState, ResourceState
    with np.load(path,allow_pickle=False) as a:
        g=GeometryState(**{n:a[n].copy() for n in ['endpoints','tx_positions','rx_positions']})
        r=ResourceState(**{n:a[n].copy() for n in ['q_matrix','q_ul','b_ul','u_s']})
        h=a['wsr_history'].astype(float).tolist() if 'wsr_history' in a else []
    return g,r,h

def config_for_task(root,p,task):
    from system_model import load_config
    from system_model import make_scene_config
    source=p['load_configs'][str(int(task['parameter_value']))] if task['figure']=='system_load' else p['base_config']
    raw=p['_models'][source];cfg=load_config(raw)
    proto=p['protocol']
    # Preserve the original objective arrays: only algorithm protocol/initial amplitude changes.
    cfg=replace(cfg,p_dl_max=proto['base_p_dl_W'],rho_si=proto['base_rho_si'],max_inner_iter=proto['max_inner_iter'],max_outer_iter=proto['max_outer_iter'],
        tol_inner=proto['tol_inner'],tol_outer=proto['tol_outer'],plateau_window=0,tol_window=0.,
        random_seed=proto['resource_seed'],kappa_ul=float(np.sqrt(proto['initial_ul_power_W']/cfg.p_ul_max[0])))
    if task['figure'] in ['p_dl_max','convergence']:cfg=replace(cfg,p_dl_max=float(task['parameter_value']))
    if task['figure']=='rho_si':cfg=replace(cfg,rho_si=float(task['parameter_value']))
    if task['figure']=='tradeoff':
        w=float(task['parameter_value'])
        cfg=replace(cfg,weight_dl=np.full(cfg.k_dl,w/(cfg.k_dl+cfg.j_ul)),weight_ul=np.full(cfg.j_ul,w/(cfg.k_dl+cfg.j_ul)),weight_s=np.full(cfg.l_target,(1-w)/cfg.l_target))
    exp=raw['experiment'];fading=exp.get('fading',{})
    scene_cfg = make_scene_config(cfg,int(task['scene_seed']),np.asarray(exp['position_jitter'],dtype=float),
        randomize_fading=bool(fading.get('enabled',False)),fading_model=fading.get('model','scalar_rayleigh'))
    annulus = exp.get('ground_annulus')
    if annulus is not None:
        altitude = float(annulus['uav_altitude_m'])
        r_min = float(annulus['horizontal_radius_min_m'])
        r_max = float(annulus['horizontal_radius_max_m'])
        if not np.all(np.isfinite([altitude,r_min,r_max])) or altitude <= 0 or not 0 <= r_min < r_max:
            raise ValueError('Invalid ground annulus altitude/radii')
        rng = np.random.default_rng(np.random.SeedSequence([int(task['scene_seed']), 104729]))
        def draw(count):
            radii = np.sqrt(r_min**2 + (r_max**2-r_min**2)*rng.random(count))
            angles = rng.uniform(0, 2*np.pi, count)
            return np.column_stack((radii*np.cos(angles), radii*np.sin(angles), np.full(count,-altitude)))
        scene_cfg = replace(scene_cfg, q_dl=draw(cfg.k_dl), q_ul=draw(cfg.j_ul), q_s=draw(cfg.l_target))
        scene_cfg.validate()
    return scene_cfg

def initial_pair(cfg,p,scheme):
    from system_model import build_geometry
    from algorithms import build_fpa_upa_geometry
    from channel_model import build_channels
    from channel_model import initialize_resources
    if scheme in ['proposed','b2']:
        theta=np.pi/4+2*np.pi*np.arange(cfg.m_uav)/cfg.m_uav
        e=np.column_stack([np.zeros(cfg.m_uav),cfg.cable_length*np.cos(theta),cfg.cable_length*np.sin(theta)])
        g=build_geometry(e,cfg,check_constraints=True)
    else:g=build_fpa_upa_geometry(cfg)
    r=initialize_resources(g,build_channels(g,cfg),cfg,np.random.default_rng(p['protocol']['resource_seed']))
    r.q_ul[:]=np.sqrt(float(p['protocol']['initial_ul_power_W']))
    return g,r

def metrics_values(g,r,cfg):
    from channel_model import build_channels
    from channel_model import compute_performance
    perf=compute_performance(build_channels(g,cfg),r,cfg)
    dl,ul,s=map(float,[sum(perf.rate_dl),sum(perf.rate_ul),sum(perf.rate_s)])
    return dict(sum_rate_dl=dl,sum_rate_ul=ul,sum_rate_comm=dl+ul,sum_rate_sensing=s,weighted_sum_rate=float(perf.weighted_sum_rate))

def check_state(g,r,cfg,p,scheme,g0=None):
    from system_model import check_resource_constraints
    from system_model import check_geometry_constraints
    from algorithms import build_fpa_upa_geometry
    import algorithms as ma
    check_resource_constraints(r,cfg)
    if scheme in ['proposed','b2']:check_geometry_constraints(g,cfg)
    elif scheme=='b6':
        base=build_fpa_upa_geometry(cfg);proto=p['protocol']
        if not ma._ma_geometry_is_feasible(g.tx_positions,g.rx_positions,np.mean(base.tx_positions,axis=0),np.mean(base.rx_positions,axis=0),proto['ma_region_size_m'],proto['ma_min_spacing_m'],cfg):raise RuntimeError('MA geometry infeasible.')
    if g0 is not None and scheme in ['b2','b3']:
        for n in ['tx_positions','rx_positions']:
            if not np.array_equal(getattr(g,n),getattr(g0,n)):raise RuntimeError('Fixed geometry changed.')


def task_key(task):return f"{task['figure']}/{float(task['parameter_value']):.12g}/scene_{task['scene_seed']}/{task['scheme']}"

def build_tasks(root,p,figure,n_mc=None):

    count=int(p['n_mc'] if n_mc is None else n_mc)
    if count<1:raise ValueError('n_mc must be positive.')
    seeds=list(range(int(p['scene_seed_start']),int(p['scene_seed_start'])+count))
    if figure=='convergence':values=list(map(float,p['convergence']['p_dl_W']));schemes=['proposed']
    elif figure=='tradeoff':values=list(map(float,p['tradeoff']['weights']));schemes=p['schemes']
    else:
        values=([10**((float(x)-30)/10) for x in p['sweeps']['p_dl_dbm']] if figure=='p_dl_max' else
                [10**(float(x)/10) for x in p['sweeps']['rho_si_db']] if figure=='rho_si' else list(map(float,p['sweeps']['loads'])))
        schemes=p['schemes']
    tasks=[dict(figure=figure,parameter_value=v,scene_seed=s,scheme=sc) for v in values for s in seeds for sc in schemes]
    if len({task_key(t) for t in tasks})!=len(tasks):raise ValueError('Duplicate task keys.')
    return tasks


def run_solver_call(cfg,p,task,g,r):
    import algorithms as algorithm, algorithms as baselines, inner_solver as inner_solver, outer_solver as outer_solver, algorithms as ma
    sc=task['scheme'];rng=np.random.default_rng(p['protocol']['resource_seed']);proto=p['protocol']
    with ExitStack() as stack:
        for mod in [algorithm,baselines,inner_solver,outer_solver,ma]:stack.enter_context(patch.object(mod,'relative_change',abs_change))
        from accelerated_adapter import main_resource_solver,attach_diagnostics
        inner_calls,position_records,last_rcg=stack.enter_context(main_resource_solver(proto['resource_solver']))
        if sc=='proposed':
            result=algorithm.run_joint_algorithm(cfg,rng=rng,verbose=False,position_update_mode='fp_aware',fp_aware_candidate_iters=2,initial_endpoints=g.endpoints.copy(),initial_resources=deepcopy(r))
            history=list(map(float,result.joint_wsr_history));iterations=result.outer_iterations
        elif sc=='b6':
            from ma_fp_aware import run_ma_fp_aware
            result, diagnostics=run_ma_fp_aware(cfg,rng=rng,verbose=False,region_size=proto['ma_region_size_m'],min_spacing=proto['ma_min_spacing_m'],initial_step=proto['ma_initial_step_m'],initial_tx_positions=g.tx_positions.copy(),initial_rx_positions=g.rx_positions.copy(),initial_resources=deepcopy(r))
            result.fp_aware_diagnostics=diagnostics
            history=list(map(float,result.wsr_history));iterations=result.iterations
        elif sc=='b2':
            result=baselines.run_fixed_toma_fp(cfg,rng=rng,initial_endpoints=g.endpoints.copy(),initial_resources=deepcopy(r));history=list(map(float,result.wsr_history));iterations=result.iterations
        elif sc=='b3':
            result=baselines.run_fpa_upa_fp(cfg,rng=rng,initial_resources=deepcopy(r));history=list(map(float,result.wsr_history));iterations=result.iterations
        else:raise ValueError('Unsupported scheme.')
        attach_diagnostics(result,sc,inner_calls,position_records,last_rcg)
        if sc in ('b2','b3'):iterations=result.iterations
    return result,history,int(iterations)


def run_task(root_string,out_string,p,task,max_calls):
    root,out=Path(root_string),Path(out_string);cfg=config_for_task(root,p,task);folder=out/'tasks'/task_key(task);folder.mkdir(parents=True,exist_ok=True)
    g0,r0=initial_pair(cfg,p,task['scheme']);check_state(g0,r0,cfg,p,task['scheme']);fingerprint=config_digest(cfg)
    if not np.allclose(np.abs(r0.q_ul)**2,float(p['protocol']['initial_ul_power_W']),rtol=0,atol=1e-12):raise RuntimeError('Generated initial UL power differs before optimization.')
    initial=folder/'initial.npz';record=folder/'record.json'
    if not initial.exists():save_state(initial,g0,r0,[])
    gi,ri,_=load_state(initial)
    for n in ['endpoints','tx_positions','rx_positions']:
        if not np.allclose(getattr(gi,n),getattr(g0,n),rtol=0,atol=1e-12):raise RuntimeError('Saved initial geometry differs.')
    if p['protocol'].get('saved_initialization_authoritative', False) and record.exists():
        check_state(gi,ri,cfg,p,task['scheme'])
        if not np.allclose(np.abs(ri.q_ul)**2, float(p['protocol']['initial_ul_power_W']), rtol=0, atol=1e-12):
            raise RuntimeError('Saved initial UL power differs.')
    else:
        for n in ['q_matrix','q_ul','b_ul','u_s']:
            if not np.allclose(getattr(ri,n),getattr(r0,n),rtol=1e-12,atol=1e-12):raise RuntimeError('Saved initial resource differs.')
    g,r,h=gi,ri,[];iterations=0;seconds=0.;call=0
    if record.exists():
        d=read_json(record)
        if d.get('solver_sha256')!=solver_digest(p) or d['cfg_sha256']!=fingerprint or d['initial_sha256']!=sha(initial) or d['state_sha256']!=sha(folder/d['state_file']):raise RuntimeError('Checkpoint identity mismatch.')
        g,r,h=load_state(folder/d['state_file']);check_state(g,r,cfg,p,task['scheme'],g0)
        if abs(metrics_values(g,r,cfg)['weighted_sum_rate']-float(d['row']['weighted_sum_rate']))>1e-9:raise RuntimeError('Checkpoint WSR mismatch.')
        if d['row']['converged']:
            required=2
            delta=np.diff(h);tol=stopping_tolerance(cfg,task['scheme'])
            if len(delta)<required or np.min(delta)<-1e-8 or np.max(abs(delta[-required:]))>tol:raise RuntimeError('Cached stopping/history mismatch.')
            return d['row']
        iterations=int(d['row']['iterations']);seconds=float(d['row']['runtime_s']);call=int(d['row']['calls'])
    # A saved iteration-limit result is final for this single-pass protocol.
    if record.exists():
        return d['row']
    if max_calls != 1:
        raise ValueError('Continuation disabled: max_calls must be 1')
    for _ in range(1):
        call+=1;expected=metrics_values(g,r,cfg)['weighted_sum_rate'];tick=time.perf_counter()
        print('START',task_key(task),'call',call,'previous_steps',iterations,flush=True)
        result,new,count=run_solver_call(cfg,p,task,g,r);seconds+=time.perf_counter()-tick
        if len(new)<2 or not np.isclose(new[0],expected,rtol=1e-9,atol=1e-9):raise RuntimeError('Initial/continuation WSR mismatch.')
        h=h+new[1:] if h else new;iterations+=count
        if np.min(np.diff(h))<-1e-8*max(1.,max(abs(x) for x in h)):raise RuntimeError('True WSR decreased.')
        g,r=result.geometry,result.resources;check_state(g,r,cfg,p,task['scheme'],g0);v=metrics_values(g,r,cfg)
        if not all(np.isfinite(x) for x in v.values()) or not np.isclose(h[-1],v['weighted_sum_rate'],rtol=1e-9,atol=1e-9):raise RuntimeError('Final metrics mismatch.')
        converged=bool(result.converged);required=2;tol=stopping_tolerance(cfg,task['scheme'])
        if converged and (len(new)<required+1 or np.max(abs(np.diff(new[-required-1:])))>tol):raise RuntimeError('Absolute stopping check failed.')
        state_name=f'call_{call:03d}.npz';save_state(folder/state_name,g,r,h)
        row=dict(**task,**v,iterations=iterations,runtime_s=seconds,converged=converged,calls=call,stop_reason='tolerance' if converged else 'iteration_limit',position_method='fp_aware_2' if task['scheme'] in ('proposed','b6') else 'fixed')
        if hasattr(result,'fp_aware_diagnostics'):
            json_write(folder/'fp_aware_diagnostics.json',result.fp_aware_diagnostics)
        inner_records=result.accelerated_inner_diagnostics
        json_write(folder/'accelerated_inner_diagnostics.json',inner_records)
        if hasattr(result,'final_rcg_state'):
            from accelerated_adapter import rcg_arrays
            np.savez_compressed(folder/'final_rcg_state.npz',**rcg_arrays(result.final_rcg_state))
        json_write(record,dict(row=row,cfg_sha256=fingerprint,solver_sha256=solver_digest(p),
            resource_solver=p['protocol']['resource_solver'],main_actual_fp_iterations=sum(x['actual_fp_iterations'] for x in inner_records),
            main_inner_converged_calls=sum(x['converged'] for x in inner_records),main_inner_calls=len(inner_records),
            history_axis='outer_iteration' if task['scheme'] in ('proposed','b6') else 'accepted_resource_block',
            iteration_count_unit='outer_iteration' if task['scheme'] in ('proposed','b6') else 'actual_fp_iteration',
            effective_config=serial(asdict(cfg)),initial_sha256=sha(initial),state_file=state_name,state_sha256=sha(folder/state_name),
            absolute_stopping=True,stopping_consecutive=2,same_parameter_scene_weight_only=True,convergence_measure="absolute_difference"))
        print('DONE',task_key(task),'WSR',v['weighted_sum_rate'],'converged',converged,'steps',iterations,flush=True)
        if converged:return row
    return row


def collect_rows(out,tasks):
    rows=[]
    for task in tasks:
        f=Path(out)/'tasks'/task_key(task)/'record.json'
        if f.exists():rows.append(read_json(f)['row'])
    return rows

def plotting():
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.grid':True,'grid.alpha':.22})
    return plt

def save_figure(fig,out,name):
    folder=Path(out)/'figures';folder.mkdir(parents=True,exist_ok=True)
    for ext in ['png','pdf','svg']:fig.savefig(folder/f'{name}.{ext}',dpi=240,facecolor='white',bbox_inches='tight')


def inside_legend(ax, **kwargs):
    """Keep the legend inside; add vertical headroom if every location is crowded."""
    for _ in range(7):
        legend=ax.legend(loc='best',framealpha=.96,**kwargs)
        ax.figure.canvas.draw()
        box=legend.get_window_extent().expanded(1.04,1.10)
        if not any(line.get_transform().transform_path(line.get_path()).intersects_bbox(box,filled=False) for line in ax.lines):
            return legend
        bottom,top=ax.get_ylim()
        ax.set_ylim(bottom,top+.18*(top-bottom))
    return legend


def summarize_sweep(rows,tasks,schemes):
    summary=[]
    for value in sorted({float(t['parameter_value']) for t in tasks}):
        for sc in schemes:
            expected=[t for t in tasks if float(t['parameter_value'])==value and t['scheme']==sc]
            selected=[r for r in rows if float(r['parameter_value'])==value and r['scheme']==sc]
            if len(selected)!=len(expected):raise RuntimeError('Incomplete Monte Carlo cell: never average partial scenes.')
            data=np.asarray([float(r['weighted_sum_rate']) for r in selected]);summary.append(dict(parameter_value=value,scheme=sc,n_scenes=len(data),n_converged=sum(r['converged'] for r in selected),mean_wsr=float(data.mean()),std_wsr=float(data.std(ddof=1)) if len(data)>1 else 0.))
    return summary

def plot_sweep(out,p,figure,tasks,rows):
    summary=summarize_sweep(rows,tasks,p['schemes']);csv_write(Path(out)/'tables'/f'{figure}_mean.csv',summary,list(summary[0]))
    plt=plotting();fig,ax=plt.subplots(figsize=(7.5,5.1))
    for sc in p['schemes']:
        a=sorted([r for r in summary if r['scheme']==sc],key=lambda r:r['parameter_value']);x=np.asarray([r['parameter_value'] for r in a]);style=STYLES[sc]
        if figure=='p_dl_max':x=10*np.log10(x)+30
        if figure=='rho_si':x=10*np.log10(x)
        ax.plot(x,[r['mean_wsr'] for r in a],color=style['color'],marker=style['marker'],label=style['label'],lw=1.7,ms=5)
    xlabel={'p_dl_max':'Maximum DL transmit power (dBm)','rho_si':'Residual SI level (dB)','system_load':'System load ($K=J=L$)'}[figure]
    ax.set_xlabel(xlabel);ax.set_ylabel('Average WSR (bit/s/Hz)');ax.set_title(f"{summary[0]['n_scenes']} scenes | budget results: {sum(r['converged'] for r in rows)}/{len(rows)} converged")
    if figure=='system_load':ax.set_xticks(p['sweeps']['loads'])
    elif figure=='p_dl_max':ax.set_xticks(p['sweeps']['p_dl_dbm'])
    else:ax.set_xticks(p['sweeps']['rho_si_db'])
    fig.tight_layout();inside_legend(ax,fontsize=9);name={'p_dl_max':'02_wsr_vs_p_dl_max','rho_si':'03_wsr_vs_rho_si','system_load':'04_wsr_vs_system_load'}[figure]
    save_figure(fig,out,name);plt.close(fig)




# ===== final_protocol: shared implementation =====
"""Frozen 100-scene protocol and deterministic multi-start initialization."""
from pathlib import Path
from unittest.mock import patch
import numpy as np
import sys
engine = sys.modules[__name__]

ROOT = Path(__file__).resolve().parent
ANCHOR = engine.initial_pair
STARTS = {'proposed': 5, 'b6': 3, 'b2': 1, 'b3': 1}


def n_starts(task):
    return 1 if task['figure'] == 'tradeoff' else STARTS[task['scheme']]


def pair(cfg, protocol, scheme, start):
    from system_model import build_geometry
    from channel_model import build_channels, initialize_resources
    import algorithms as ma
    frozen=protocol.get('_frozen_geometry',{}).get(scheme)
    if frozen is not None:
        if start != 0: raise ValueError('Frozen protocol has exactly one start')
        if scheme=='proposed':
            g=build_geometry(np.asarray(frozen['endpoints'],dtype=float),cfg,check_constraints=True)
        elif scheme=='b6':
            g=ma._build_ma_geometry(np.asarray(frozen['tx_positions'],dtype=float),np.asarray(frozen['rx_positions'],dtype=float),cfg)
        else: raise ValueError('Unexpected frozen scheme')
    else:
        g,_=ANCHOR(cfg,protocol,scheme)
        if start>0:
            rng=np.random.default_rng(np.random.SeedSequence([20261023,0 if scheme=='proposed' else 1,start]))
            if scheme=='proposed':
                anchor=g.endpoints/cfg.cable_length
                for _ in range(cfg.max_geometry_trials):
                    directions=anchor+.15*rng.normal(size=anchor.shape)
                    endpoints=cfg.cable_length*directions/np.linalg.norm(directions,axis=1,keepdims=True)
                    try: g=build_geometry(endpoints,cfg,check_constraints=True); break
                    except ValueError: continue
                else: raise RuntimeError('No feasible screening geometry')
            elif scheme=='b6':
                q=protocol['protocol']
                g=ma._randomize_initial_ma_geometry(g,np.mean(g.tx_positions,axis=0),np.mean(g.rx_positions,axis=0),q['ma_region_size_m'],q['ma_min_spacing_m'],.5,cfg,rng)
            else: raise ValueError('Fixed arrays have only start zero')
    r=initialize_resources(g,build_channels(g,cfg),cfg,np.random.default_rng(protocol['protocol']['resource_seed']))
    r.q_ul[:]=np.sqrt(protocol['protocol']['initial_ul_power_W'])
    return g,r


def run_job(job):
    out, protocol, task, start, max_calls = job
    with patch.object(engine, 'initial_pair', lambda cfg, p, sc: pair(cfg, p, sc, start)):
        row = engine.run_task(str(ROOT), str(Path(out)/f'candidate_{start}'),
                              protocol, task, max_calls)
    return dict(row, start_id=start)


def read_verified(out, protocol, task, start):
    folder = Path(out)/f'candidate_{start}'/'tasks'/engine.task_key(task)
    record = folder/'record.json'
    if not record.exists():
        return None
    d = engine.read_json(record)
    cfg = engine.config_for_task(ROOT, protocol, task)
    if any(d['row'].get(k) != v for k, v in task.items()):
        raise RuntimeError('Checkpoint task mismatch')
    if d['cfg_sha256'] != engine.config_digest(cfg):
        raise RuntimeError('Checkpoint config mismatch')
    if d.get('solver_sha256')!=solver_digest(protocol):
        raise RuntimeError('Resource solver identity mismatch')
    if d['initial_sha256'] != engine.sha(folder/'initial.npz') or d['state_sha256'] != engine.sha(folder/d['state_file']):
        raise RuntimeError('Checkpoint checksum mismatch')
    g0, r0, _ = engine.load_state(folder/'initial.npz')
    expected, resources = pair(cfg, protocol, task['scheme'], start)
    for name in ('endpoints', 'tx_positions', 'rx_positions'):
        if not np.allclose(getattr(g0, name), getattr(expected, name), rtol=0, atol=1e-12):
            raise RuntimeError('Checkpoint initial geometry mismatch')
    for name in ('q_matrix', 'q_ul', 'b_ul', 'u_s'):
        if not np.allclose(getattr(r0, name), getattr(resources, name), rtol=1e-12, atol=1e-12):
            raise RuntimeError('Checkpoint initial resource mismatch')
    if not np.allclose(abs(r0.q_ul)**2, .025, rtol=0, atol=1e-12):
        raise RuntimeError('Initial UL power must be 25 mW')
    g, r, h = engine.load_state(folder/d['state_file'])
    engine.check_state(g, r, cfg, protocol, task['scheme'], g0)
    if abs(engine.metrics_values(g, r, cfg)['weighted_sum_rate']-d['row']['weighted_sum_rate']) > 1e-8:
        raise RuntimeError('Checkpoint metrics mismatch')
    if d['row']['converged']:
        required = 2
        delta = np.diff(h)
        if len(delta) < required or not np.all(np.isfinite(h)) or np.min(delta) < -1e-8*max(1., max(abs(x) for x in h)) or max(abs(delta[-required:])) > stopping_tolerance(cfg,task['scheme']):
            raise RuntimeError('Absolute convergence verification failed')
    return dict(d['row'], start_id=start)


def plot_convergence(out, protocol, tasks, winners):
    histories = []
    for power in protocol['convergence']['p_dl_W']:
        group = [r for r in winners if r['parameter_value'] == power]
        for row in group:
            task = {k:row[k] for k in ('figure','parameter_value','scene_seed','scheme')}
            folder = Path(out)/f"candidate_{row['start_id']}"/'tasks'/engine.task_key(task)
            d = engine.read_json(folder/'record.json')
            _, _, h = engine.load_state(folder/d['state_file'])
            histories.extend(dict(p_dl_W=power,scene_seed=row['scene_seed'],start_id=row['start_id'],iteration=j,weighted_sum_rate=v) for j,v in enumerate(h))
    plot_convergence_histories(out,protocol,histories)
    engine.csv_write(Path(out)/'tables/convergence_histories.csv',histories,list(histories[0]))


def plot_convergence_histories(out, protocol, histories):
    plt=engine.plotting()
    fig,ax=plt.subplots(figsize=(8.4,5.6))
    overview=ax.inset_axes([.56,.12,.40,.39])
    overview.set_title('Full trajectory',fontsize=9)
    overview.tick_params(labelsize=8)
    overview.set_xlabel('Iteration',fontsize=8)
    counts=[];longest=0
    for i,power in enumerate(protocol['convergence']['p_dl_W']):
        cells={}
        for row in histories:
            if float(row['p_dl_W'])==power:
                cells.setdefault((int(row['scene_seed']),int(row['start_id'])),[]).append(row)
        hs=[]
        for cell in cells.values():
            cell=sorted(cell,key=lambda r:int(r['iteration']))
            if [int(r['iteration']) for r in cell]!=list(range(len(cell))):
                raise RuntimeError('Missing or duplicate convergence iteration')
            h=np.asarray([float(r['weighted_sum_rate']) for r in cell])
            if not np.all(np.isfinite(h)) or len(h)<2:
                raise RuntimeError('Invalid convergence history')
            hs.append(h)
        if not hs: raise RuntimeError('Missing convergence power')
        counts.append(len(hs));length=max(map(len,hs));longest=max(longest,length-1)
        # Keep every scene, including long tails; edge padding is only for the mean.
        matrix=np.asarray([np.pad(h,(0,max(101,length)-len(h)),mode='edge') for h in hs])
        mean=matrix.mean(axis=0)
        style=dict(color=engine.POWER_COLORS[i],linestyle=engine.POWER_LINESTYLES[i])
        ax.plot(np.arange(101),mean[:101],label=f'{10*np.log10(power)+30:g} dBm',**style)
        overview.plot(np.arange(length),mean[:length],lw=1.1,**style)
    if len(set(counts))!=1: raise RuntimeError('Different scene counts across convergence powers')
    ax.set(xlim=(0,100),xlabel='Joint AO iteration',ylabel='Mean WSR (bit/s/Hz)',title=f'{counts[0]} historically selected scenes | frozen initial geometry; budget results')
    ax.set_ylim(bottom=0)
    overview.set_xlim(0,max(1,longest));overview.set_ylim(bottom=0)
    # Both boxes sit below the converged curves in the common layout.
    ax.legend(title='Maximum DL power',loc='lower left',bbox_to_anchor=(.02,.08),fontsize=9)
    fig.text(.1,.015,'Stopped scenes retain their terminal WSR; no scenes are trimmed.',fontsize=8)
    fig.tight_layout(rect=(0,.04,1,1))
    engine.save_figure(fig,out,'01_proposed_convergence')
    plt.close(fig)


def plot_tradeoff(out, protocol, tasks, rows):
    summary = []
    for w in protocol['tradeoff']['weights']:
        for sc in protocol['schemes']:
            group = [r for r in rows if r['parameter_value']==w and r['scheme']==sc]
            summary.append(dict(omega_comm=w,scheme=sc,n_scenes=len(group),
                mean_comm=float(np.mean([r['sum_rate_comm'] for r in group])),
                mean_sensing=float(np.mean([r['sum_rate_sensing'] for r in group]))))
    engine.csv_write(Path(out)/'tables/tradeoff_mean.csv',summary,list(summary[0]))
    plt = engine.plotting()
    fig,ax = plt.subplots(figsize=(8.4,6.1))
    for sc in protocol['schemes']:
        group = [r for r in summary if r['scheme']==sc]
        style = engine.STYLES[sc]
        ax.plot([r['mean_comm'] for r in group],[r['mean_sensing'] for r in group],
            color=style['color'],marker=style['marker'],label=style['label'])
    ax.set(xlabel='Mean communication rate (bit/s/Hz)',ylabel='Mean sensing rate (bit/s/Hz)',
           title=f"{group[0]['n_scenes']} Monte Carlo scenes | common initial geometry across weights")
    ax.set_xlim(left=0);ax.set_ylim(bottom=0)
    ax.set_title(f"Single-pass budget results | {sum(bool(r['converged']) for r in rows)}/{len(rows)} tasks converged")
    fig.tight_layout()
    inside_legend(ax,fontsize=9)
    engine.save_figure(fig,out,'05_communication_sensing_tradeoff')
    plt.close(fig)


def replot_exports(source, out, protocol, figures, n_mc=None):
    """Read exported tables, never adopt/edit checkpoints or run an optimizer.

    Old results retain their original source identity. A separate render manifest
    records input CSV hashes and the exact scene subset used for the new figures.
    """
    source,out=Path(source).resolve(),Path(out).resolve()
    if out==source or source in out.parents:
        raise ValueError('Replot output must be outside the source run directory')
    if out.exists():
        raise FileExistsError('Use a new replot output directory; existing data will not be overwritten')
    inputs={};prepared=[]

    def read_table(name):
        path=source/'tables'/name
        inputs[str(path)]=sha(path)
        with path.open(encoding='utf-8-sig',newline='') as handle:
            data=list(csv.DictReader(handle))
        if not data: raise RuntimeError(f'Empty exported table: {path}')
        return data

    for figure in figures:
        rows=read_table(f'{figure}_per_scene.csv')
        for row in rows:
            if row['figure']!=figure: raise RuntimeError('Exported figure identity mismatch')
            for key in ('parameter_value','weighted_sum_rate','sum_rate_comm','sum_rate_sensing'):
                if key in row:
                    row[key]=float(row[key])
                    if not np.isfinite(row[key]): raise RuntimeError('Non-finite exported metric')
            for key in ('scene_seed','start_id','iterations','calls'):
                if key in row: row[key]=int(row[key])
            if str(row['converged']).lower() not in ('true','1'):
                raise RuntimeError('Cannot plot an unconverged exported scene')
            row['converged']=True
        seeds=sorted({r['scene_seed'] for r in rows})
        count=n_mc if n_mc is not None else int(protocol['convergence'].get('n_mc',30)) if figure=='convergence' else len(seeds)
        selected=set(range(int(protocol['scene_seed_start']),int(protocol['scene_seed_start'])+count))
        rows=[r for r in rows if r['scene_seed'] in selected]
        p=deepcopy(protocol)
        # Replot the weights actually computed, including old grids. Missing new
        # weights must be simulated, never interpolated or fabricated for export.
        if figure=='tradeoff':
            p['tradeoff']['weights']=sorted({r['parameter_value'] for r in rows})
            if not p['tradeoff']['weights']: raise RuntimeError('No exported tradeoff weights')
        tasks=build_tasks(ROOT,p,figure,count)
        expected={task_key(t) for t in tasks}
        keys=[task_key(r) for r in rows]
        if len(keys)!=len(set(keys)) or set(keys)!=expected:
            raise RuntimeError('Incomplete or duplicate exported scene cells; no partial averages')
        histories=None
        if figure=='convergence':
            raw=read_table('convergence_histories.csv')
            winners={(r['parameter_value'],r['scene_seed'],r['start_id']):r for r in rows}
            histories=[];cells={}
            for r in raw:
                cell=(float(r['p_dl_W']),int(r['scene_seed']),int(r['start_id']))
                if cell not in winners: continue
                value=dict(p_dl_W=cell[0],scene_seed=cell[1],start_id=cell[2],iteration=int(r['iteration']),weighted_sum_rate=float(r['weighted_sum_rate']))
                histories.append(value);cells.setdefault(cell,[]).append(value)
            if set(cells)!=set(winners): raise RuntimeError('Missing exported winner histories')
            for cell,history in cells.items():
                history=sorted(history,key=lambda r:r['iteration'])
                h=np.asarray([r['weighted_sum_rate'] for r in history])
                if [r['iteration'] for r in history]!=list(range(len(h))) or len(h)<3 or not np.all(np.isfinite(h)):
                    raise RuntimeError('Invalid exported trajectory')
                if np.min(np.diff(h)) < -1e-8*max(1.,float(np.max(np.abs(h)))) or np.max(np.abs(np.diff(h)[-2:]))>1e-4:
                    raise RuntimeError('Exported convergence trajectory fails stopping/monotonicity checks')
                if not np.isclose(h[-1],winners[cell]['weighted_sum_rate'],rtol=1e-9,atol=1e-9):
                    raise RuntimeError('Exported trajectory terminal value differs from per-scene result')
        prepared.append((figure,p,tasks,rows,histories,count))
    out.mkdir(parents=True)
    rendered={}
    for figure,p,tasks,rows,histories,count in prepared:
        csv_write(out/'tables'/f'{figure}_per_scene.csv',rows,list(rows[0]))
        if figure=='convergence':
            plot_convergence_histories(out,p,histories)
            csv_write(out/'tables/convergence_histories.csv',histories,list(histories[0]))
        elif figure=='tradeoff': plot_tradeoff(out,p,tasks,rows)
        else: plot_sweep(out,p,figure,tasks,rows)
        rendered[figure]=dict(n_mc=count,scene_seeds=sorted({r['scene_seed'] for r in rows}),parameter_values=sorted({r['parameter_value'] for r in rows}))
    if any(sha(path)!=digest for path,digest in inputs.items()):
        raise RuntimeError('Source export changed while plotting; do not use this render')
    json_write(out/'render_manifest.json',dict(mode='exported_csv_replot_no_optimization',source=str(source),input_sha256=inputs,figures=rendered,solvers_invoked=False))
    print(f'Replotted existing exports to {out}; no optimization or checkpoint writes.',flush=True)
